package db

import "fmt"

// RecordingStatus enumerates the canonical transcription-lifecycle states
// stored in the recordings.transcription_status column.
//
// The set is fixed by the Phase 1 ↔ Phase 2 contract for the
// mvp_library_export track: the storage layer guarantees that the four
// values below are the only ones used by *new* code paths, while the UI
// (LibraryView status badge) maps them to user-facing labels:
//
//	pending      → "New"
//	in_progress  → "Transcribing"
//	completed    → "Transcribed"
//	error        → "Error"
//
// Existing callers (e.g. internal/lifecycle/repairer.go) may still write
// free-form strings such as "unavailable"; those rows remain queryable via
// the untyped List/Get APIs but are intentionally excluded from
// ListByStatus, which validates its argument.
type RecordingStatus string

const (
	// StatusPending indicates the recording has not been transcribed yet.
	StatusPending RecordingStatus = "pending"
	// StatusInProgress indicates transcription is currently running.
	StatusInProgress RecordingStatus = "in_progress"
	// StatusCompleted indicates transcription finished successfully.
	StatusCompleted RecordingStatus = "completed"
	// StatusError indicates transcription failed.
	StatusError RecordingStatus = "error"
)

// IsValid reports whether s is one of the canonical RecordingStatus values.
func (s RecordingStatus) IsValid() bool {
	switch s {
	case StatusPending, StatusInProgress, StatusCompleted, StatusError:
		return true
	default:
		return false
	}
}

// ValidRecordingStatuses returns the canonical set of recording statuses
// in declaration order. Useful for UI dropdowns and exhaustive tests.
func ValidRecordingStatuses() []RecordingStatus {
	return []RecordingStatus{
		StatusPending,
		StatusInProgress,
		StatusCompleted,
		StatusError,
	}
}

// ValidateRecordingStatus returns nil when s is a canonical
// RecordingStatus value, otherwise an error describing the violation.
//
// This helper is exposed so caller layers (services, controllers, UI) can
// reject invalid statuses *before* persisting. The Insert/Update methods
// on RecordingRepository deliberately do *not* call this helper, in order
// to remain backward-compatible with existing free-form callers.
func ValidateRecordingStatus(s string) error {
	if !RecordingStatus(s).IsValid() {
		return fmt.Errorf("invalid recording status %q: must be one of %v", s, ValidRecordingStatuses())
	}
	return nil
}

